function selectionSort(nums) {
  const n = nums.length;
  for (let i = 0; i < n - 1; i++) {
    let min = i;
    for (let j = i + 1; j < n; j++) {
      if (nums[j] < nums[min]) min = j;            // remember the smallest so far
    }
    [nums[i], nums[min]] = [nums[min], nums[i]];   // put it at the front of the unsorted part
  }
  return nums;
}

def selection_sort(nums):
    n = len(nums)
    for i in range(n - 1):
        smallest = i
        for j in range(i + 1, n):
            if nums[j] < nums[smallest]:
                smallest = j                      # remember the smallest so far
        nums[i], nums[smallest] = nums[smallest], nums[i]   # put it at the front of the unsorted part
    return nums

int[] selectionSort(int[] nums) {
    int n = nums.length;
    for (int i = 0; i < n - 1; i++) {
        int min = i;
        for (int j = i + 1; j < n; j++) {
            if (nums[j] < nums[min]) min = j;     // remember the smallest so far
        }
        int t = nums[i];                          // put it at the front of the unsorted part
        nums[i] = nums[min];
        nums[min] = t;
    }
    return nums;
}

